import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyPhuongTien = () => {
    const [viewRoom, setViewRoom] = useState(null);
    const [loading, setLoading] = useState(false);

    // ĐẦU CHỜ BACKEND: Đây là mảng chứa danh sách xe của PHÒNG ĐANG CHỌN
    const [vehicleList, setVehicleList] = useState([]);

    // Khởi tạo danh sách 45 phòng (9 tầng x 5 phòng)
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // --- TỐI ƯU BACKEND: FETCH DỮ LIỆU KHI CHỌN PHÒNG ---
    useEffect(() => {
        if (!viewRoom) return;

        const fetchVehiclesByRoom = async () => {
            setLoading(true);
            try {
                /* SAU NÀY GẮN API:
                const res = await axios.get(`/api/vehicles/${viewRoom}`);
                setVehicleList(res.data); // Giả sử res.data là mảng [{type, plate}, ...]
                */

                // Tạm thời set mảng rỗng để bạn thấy giao diện chờ
                setVehicleList([]); 
            } catch (error) {
                console.error("Lỗi lấy dữ liệu xe:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchVehiclesByRoom();
    }, [viewRoom]); // Mỗi khi số phòng thay đổi, useEffect này sẽ tự chạy lại

    return (
        <div style={containerStyle} className="glass-card">

            {/* Header */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🚗 QUẢN LÝ PHƯƠNG TIỆN</h2>
            </div>

            <div style={contentWrapperStyle}>

                {/* CỘT TRÁI: CHỌN SỐ PHÒNG (Giống form Quản lý hóa đơn) */}
                <div className="custom-scrollbar" style={sidebarStyle}>
                    {allRooms.map(room => (
                        <div key={room} onClick={() => setViewRoom(room)}
                            style={{ 
                                ...roomItemStyle,
                                background: viewRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: viewRoom === room ? '#fff' : '#333',
                            }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: HIỂN THỊ DỮ LIỆU TỪ BACKEND */}
                <div style={mainContentStyle}>
                    {loading ? (
                        <div style={centerTextStyle}>ĐANG TRUY XUẤT DỮ LIỆU PHÒNG {viewRoom}...</div>
                    ) : viewRoom ? (
                        <div style={{ animation: 'fadeIn 0.3s', display: 'flex', flexDirection: 'column', height: '100%' }}>

                            {/* Tiêu đề Số phòng lớn */}
                            <div style={roomHeaderContainer}>
                                <span style={subTitleStyle}>DANH SÁCH XE</span>
                                <h1 style={roomNumberStyle}>PHÒNG {viewRoom}</h1>
                            </div>

                            {/* Danh sách xe đổ từ vehicleList */}
                            <div className="custom-scrollbar" style={listContainerStyle}>
                                {vehicleList.length > 0 ? vehicleList.map((vehicle, index) => (
                                    <div key={index} style={vehicleCardStyle}>
                                        <div style={rowStyle}>
                                            <span style={labelStyle}>Loại xe:</span>
                                            <span style={valueStyle}>{vehicle.type}</span>
                                        </div>
                                        <div style={rowStyle}>
                                            <span style={labelStyle}>Biển số:</span>
                                            <span style={{...valueStyle, color: '#8b5e5e'}}>{vehicle.plate}</span>
                                        </div>
                                    </div>
                                )) : (
                                    <div style={centerTextStyle}>
                                        <p style={{ fontSize: '18px', color: '#999' }}>Không tìm thấy dữ liệu xe cho phòng này.</p>
                                    </div>
                                )}
                            </div>

                        </div>
                    ) : (
                        <div style={centerTextStyle}>Vui lòng chọn một số phòng ở bên trái...</div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

// --- STYLES TỐI ƯU ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)' };
const headerStyle = { padding: '20px', background: 'rgba(0,0,0,0.2)' };
const contentWrapperStyle = { flex: 1, padding: '20px', display: 'flex', gap: '25px', overflow: 'hidden' };
const sidebarStyle = { width: '220px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '8px', alignContent: 'flex-start', overflowY: 'auto', padding: '15px', backgroundColor: 'rgba(0,0,0,0.3)', borderRadius: '20px' };
const roomItemStyle = { padding: '12px 0', borderRadius: '10px', textAlign: 'center', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s' };
const mainContentStyle = { flex: 1, backgroundColor: '#fff', borderRadius: '30px', padding: '40px', display: 'flex', flexDirection: 'column', color: '#333' };
const roomHeaderContainer = { borderBottom: '3px solid #8b5e5e', paddingBottom: '20px', marginBottom: '30px' };
const subTitleStyle = { fontSize: '16px', color: '#8b5e5e', fontWeight: 'bold' };
const roomNumberStyle = { fontSize: '50px', margin: 0, fontWeight: '900' };
const listContainerStyle = { flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' };
const vehicleCardStyle = { padding: '20px', backgroundColor: '#f9f9f9', borderRadius: '20px', border: '1px solid #eee' };
const rowStyle = { display: 'flex', justifyContent: 'space-between', marginBottom: '5px' };
const labelStyle = { color: '#777', fontSize: '16px' };
const valueStyle = { fontWeight: 'bold', fontSize: '18px' };
const centerTextStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', textAlign: 'center', color: '#ccc', fontStyle: 'italic' };

export default QuanLyPhuongTien;
